import sys
from collections import defaultdict, deque

sys.setrecursionlimit(2 * 10**5)

def dfs(node, parent):
    for child in tree[node]:
        if child != parent:
            depth[child] = depth[node] + 1
            parent_list[child] = node
            dfs(child, node)

def lca(u, v):
    if depth[u] < depth[v]:
        u, v = v, u
    while depth[u] > depth[v]:
        u = parent_list[u]
    while u != v:
        u = parent_list[u]
        v = parent_list[v]
    return u

def get_dis(u, lca_node):
    path = []
    while u != lca_node:
        path.append(s[u - 1])
        u = parent_list[u]
    return path[::-1]

def is_palindrome(s):
    return s == s[::-1]

def check_palindrome_subsequence(s):
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n):
            if is_palindrome(s[i:j]):
                return True
    return False

def solve(N, S, edges, queries):
    global tree, parent_list, depth, s
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    parent_list = [0] * (N + 1)
    depth = [0] * (N + 1)
    dfs(1, -1)

    for u, v in queries:
        lca_node = lca(u, v)
        dis_u = get_dis(u, lca_node)
        dis_v = get_dis(v, lca_node)
        combined_dis = dis_u + dis_v
        if check_palindrome_subsequence(combined_dis):
            print("YES")
        else:
            print("NO")

